import {writeFile,readFile,readdir} from 'node:fs/promises';
import {createHash} from 'node:crypto';
const variant=process.argv[2],workload=process.argv[3],trial=Number(process.argv[4]);
const hash=x=>createHash('sha256').update(x).digest('hex');
const sourceTree=createHash('sha256');
for(const name of (await readdir(new URL(`./${variant}/`,import.meta.url))).filter(x=>x.endsWith('.ts')).sort())sourceTree.update(name).update(await readFile(new URL(`./${variant}/${name}`,import.meta.url)));
const imported=performance.now();const {FrameAnalyzer}=await import(`./${variant}/index.ts`);const importMs=performance.now()-imported;
const w=1920,h=1080,frames=90,warmup=15;
const visualField={widthPx:682,heightPx:512,basis:'W3C_CSS_REFERENCE',reference:'Numeric profiling assumption: 341x256 CSS reference at DPR2 and standard zoom. No physical display measurement.'};
const analyzer=new FrameAnalyzer({maxPixels:w*h,visualField});const preparing=performance.now();analyzer.prepare(w,h);const prepareMs=performance.now()-preparing;
const image=new Uint8ClampedArray(w*h*4),noise=new Uint32Array(w*h);
for(let p=0;p<noise.length;p++){let n=Math.imul(p^0x6d2b79f5,0x45d9f3b);n=Math.imul(n^(n>>>16),0x45d9f3b);noise[p]=(n^(n>>>16))>>>0}
let texture;if(workload==='translation'){texture=new Uint8Array(image.length);for(let y=0;y<h;y++)for(let x=0;x<w;x++){const p=y*w+x,i=p*4,v=Math.round(100+35*Math.sin(x/61)+25*Math.cos(y/47)+20*Math.sin((x+y)/113)+(noise[p]&7));texture[i]=v;texture[i+1]=v+15;texture[i+2]=v-10;texture[i+3]=255}}
const times=[];
for(let f=0;f<frames;f++){
 const phase=Math.floor(f*8/60)%2;
 for(let p=0;p<noise.length;p++){const i=p*4,n=noise[p];
  if(texture){const src=(Math.floor(p/w)*w+((p%w+f)%w))*4;image[i]=texture[src];image[i+1]=texture[src+1];image[i+2]=texture[src+2]}
  else if(workload==='gradient'){const value=(p+f*3)%256;image[i]=value;image[i+1]=(value+71)%256;image[i+2]=(value+133)%256}
  else if(workload==='pulse'){image[i]=image[i+1]=image[i+2]=phase?255:0}
  else if(workload==='sparse'){const x=p%w,y=Math.floor(p/w);image[i]=image[i+1]=image[i+2]=(x>=955&&x<965&&y>=535&&y<545&&phase)?255:0}
  else{image[i]=((n&255)+f*3)&255;image[i+1]=(((n>>>8)&255)+f*3)&255;image[i+2]=(((n>>>16)&255)+f*3)&255}image[i+3]=255
 }
 const t=performance.now();analyzer.pushFrame({rgba:image,width:w,height:h,timestampMs:f*1000/60});if(f>=warmup)times.push(performance.now()-t);
}
const result=analyzer.finish(),sorted=[...times].sort((a,b)=>a-b);
const summary={variant,workload,trial,sourceTreeSha256:sourceTree.digest('hex'),width:w,height:h,frames,warmup,arrayType:'Uint8ClampedArray',visualField,importMs,prepareMs,meanMs:times.reduce((a,b)=>a+b,0)/times.length,p95Ms:sorted[Math.ceil(times.length*.95)-1],maxMs:Math.max(...times),framesOver16_7Ms:times.filter(t=>t>1000/60).length,stateBytes:result.quality.spatial.stateBytes,resultSha256:hash(JSON.stringify(result)),findings:result.findings.length,times};
await writeFile(new URL(`./${variant}-${workload}-${trial}.json`,import.meta.url),JSON.stringify(summary,null,2),{flag:'wx'});
console.log(JSON.stringify({...summary,times:undefined,visualField:undefined}));

