import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {readFile,readdir,writeFile} from 'node:fs/promises';
import {FrameAnalyzer as Baseline} from './baseline/index.ts';
import {FrameAnalyzer as Packed} from './packed_direct/index.ts';
const hash=v=>createHash('sha256').update(v).digest('hex');
async function sourceHash(variant) {
 const tree=createHash('sha256');
 for(const name of (await readdir(new URL(`./${variant}/`,import.meta.url))).filter(x=>x.endsWith('.ts')).sort())tree.update(name).update(await readFile(new URL(`./${variant}/${name}`,import.meta.url)));
 return tree.digest('hex');
}
const manifest=JSON.parse(await readFile(new URL('../combined-manifest.json',import.meta.url)));
const before={baseline:await sourceHash('baseline'),packed:await sourceHash('packed_direct')};
assert.equal(before.baseline,manifest.baselineEngineSourceTreeSha256);
assert.equal(before.packed,manifest.prototypeEngineSourceTreeSha256);
const records=[];let findings=0,liveEvents=0,packedFrames=0;
for(const [w,h] of [[1,1],[19,17],[64,49]])
for(const mode of ['uniform','red','dense','dense-red','alias-fork','alpha-black','source-gap'])
for(const format of ['uint8-aligned','clamped-aligned','mixed-alignment'])
for(const diagnostics of [true,false]) {
 const key=`${w}x${h}/${mode}/${format}/${diagnostics}`;
 const eventsA=[],eventsB=[];
 const options={maxPixels:(w+1)*h,diagnostics,visualField:{widthPx:341,heightPx:256,basis:'W3C_CSS_REFERENCE',reference:'Fixed differential field; no display measurement'}};
 const a=new Baseline({...options,onCandidate:f=>eventsA.push(structuredClone(f))});
 const b=new Packed({...options,onCandidate:f=>eventsB.push(structuredClone(f))});
 let calls=0;const dense=b.processDensePacked;
 b.processDensePacked=function(words){calls++;return dense.call(this,words)};
 for(let f=0;f<160;f++) {
  const width=w+(mode==='source-gap'&&f>=110?1:0),height=h;
  const offset=format==='mixed-alignment'?(f%3===0?1:0):0;
  const buffer=new ArrayBuffer(width*height*4+offset);
  const Type=format==='clamped-aligned'||(format==='mixed-alignment'&&f%2)?Uint8ClampedArray:Uint8Array;
  const rgba=new Type(buffer,offset,width*height*4),phase=Math.floor(f/5)%2;
  for(let p=0;p<width*height;p++) {
   const i=p*4;let r,g,blue;
   if(mode==='uniform'||(mode==='alias-fork'&&(f<35||f>=100)))r=g=blue=phase?230:10;
   else if(mode==='red'){r=phase?255:0;g=phase?0:255;blue=0;}
   else {let n=Math.imul(p^0x6d2b79f5,0x45d9f3b);n=Math.imul(n^(n>>>16),0x45d9f3b);n=(n^(n>>>16))>>>0;
    r=(n&63)+(phase?180:0);g=((n>>>8)&63)+(phase?180:0);blue=((n>>>16)&63)+(phase?180:0);
    if(mode==='dense-red'&&p%3===0){r=phase?230+(n&15):0;g=phase?0:230+((n>>>8)&15);blue=0;}
   }
   if(mode==='alpha-black'&&f>=75&&f<80&&p%7===0)r=g=blue=0;
   rgba[i]=r;rgba[i+1]=g;rgba[i+2]=blue;rgba[i+3]=mode==='alpha-black'&&f>=50&&f<54&&p%11===0?120:255;
  }
  const frame={rgba,width,height,timestampMs:f*1000/60+(mode==='source-gap'&&f>=80?140:0),sourceWidth:mode==='source-gap'&&f>=90?width*2:width,sourceHeight:height};
  a.pushFrame(frame);b.pushFrame(frame);
  if(mode==='source-gap'&&f===130){a.markInterrupted('Exact comparison interruption');b.markInterrupted('Exact comparison interruption')}
 }
 const expected=a.finish(),actual=b.finish();
 assert.deepEqual(actual,expected,key);
 assert.deepEqual(eventsB,eventsA,`live events ${key}`);
 findings+=actual.findings.length;liveEvents+=eventsB.length;packedFrames+=calls;
 records.push({key,packedFrames:calls,findings:actual.findings.length,liveEvents:eventsB.length,resultSha256:hash(JSON.stringify(actual)),eventsSha256:hash(JSON.stringify(eventsB))});
}
assert.ok(packedFrames>0,'The optimized route must actually execute');
for(const format of ['uint8-aligned','clamped-aligned','mixed-alignment'])assert.ok(records.some(r=>r.key.includes(format)&&r.packedFrames>0));
assert.deepEqual({baseline:await sourceHash('baseline'),packed:await sourceHash('packed_direct')},before);
const result={scope:'Exact complete finish() and live callback differential; both byte array types, unaligned fallback, alpha and black resets, aliases that fork/reconverge, source geometry changes, timestamp gaps and explicit interruption. Numeric buffers only, never rendered.',cases:records.length,findings,liveEvents,packedFrames,sourceHashes:before,completeResultsIdentical:true,liveEventsIdentical:true,records};
await writeFile(new URL('./combined-proof.json',import.meta.url),JSON.stringify(result,null,2),{flag:'wx'});
console.log(JSON.stringify({...result,records:undefined}));
